insert into public.hero_stats (value,label,sort) values ('20','Specialist services under one roof',0),('7','Service areas, from strategy to support',1),('Free','First consultation for every new client',2);
insert into public.blog_posts (slug,title,category,published_on,author,featured,image,excerpt,intro_keyword,intro_text,sections) values ('what-a-data-modernization-project-involves','What a data modernization project actually involves','Data','2026-09-28','AchiveX Editorial Team',true,'https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?auto=format&fit=crop&w=2000&q=80','A plain account of the stages, the decisions and the people you need for a data platform upgrade.','Data modernization',' is the process of moving reporting and analysis away from scattered spreadsheets and ageing databases onto a platform designed for it. The phrase sounds large, but most projects follow the same handful of stages.','[{"id":"start-with-an-inventory","heading":"Start with an inventory","paragraphs":["Before choosing any technology, list every data source that feeds a report people rely on. Note who owns it, how often it changes and which reports depend on it. This list will drive the rest of the project.","Teams are often surprised by how many sources turn up. A single monthly report can depend on a CRM export, two spreadsheets and a query someone wrote years ago."]},{"id":"choose-a-target-platform","heading":"Choose a target platform","paragraphs":["Cloud data warehouses and lakehouse platforms from the major providers all handle typical business volumes well. The right choice usually depends on the cloud you already use, the skills on your team and how you prefer to pay."],"list":["Which cloud provider do you already use?","Who will maintain pipelines after launch?","Do you need to store raw files as well as tables?"]},{"id":"migrate-in-waves","heading":"Migrate in waves","paragraphs":["Moving everything at once is risky. A better approach is to pick one subject area, such as sales, move its sources, rebuild its reports and reconcile the numbers against the old version before moving on.","Reconciliation is where trust is earned. If finance sees the same totals in the new reports as the old ones, adoption follows."]},{"id":"plan-the-handover","heading":"Plan the handover","paragraphs":["A platform is only useful if someone can run it. Document pipelines, set up alerts for failures and train the people who will look after it. Then switch off the old pieces so there is only one place to look."]}]'::jsonb),('cloud-costs-five-habits','Five habits that keep cloud costs predictable','Cloud','2026-08-30','AchiveX Editorial Team',false,'https://images.unsplash.com/photo-1607799279861-4dd421887fb3?auto=format&fit=crop&w=1600&q=80','Simple routines for tagging, budgets and reviews that stop surprise bills.','Cloud cost management',' is less about clever tools and more about steady habits. These five are simple to adopt and make a noticeable difference.','[{"id":"tag-everything","heading":"Tag everything","paragraphs":["Every resource should carry tags for owner, environment and project. Without tags, nobody can say who is responsible for a line on the bill."]},{"id":"set-budgets-and-alerts","heading":"Set budgets and alerts","paragraphs":["All major providers let you set budgets with email alerts. Set them per project and per environment so problems show up early."]},{"id":"switch-off-what-is-idle","heading":"Switch off what is idle","paragraphs":["Development and test environments rarely need to run overnight or at weekends. Scheduled shutdowns are one of the easiest savings available."]},{"id":"rightsize-regularly","heading":"Rightsize regularly","paragraphs":["Instances are often sized for a launch that never needed that capacity. Review utilisation monthly and resize where usage is consistently low."]},{"id":"review-commitments","heading":"Review commitments","paragraphs":["Reserved capacity and savings plans can lower costs for steady workloads. Commit only once usage has been stable for a while."]}]'::jsonb),('multi-factor-authentication-first','Why multi factor authentication should come first','Security','2026-07-14','AchiveX Editorial Team',false,'https://images.unsplash.com/photo-1563986768494-4dee2763ff3f?auto=format&fit=crop&w=1600&q=80','Of all the security controls a small business can add, this one gives the most protection for the effort.','Multi factor authentication',' asks users for a second proof of identity, such as an app prompt or a hardware key, in addition to a password. It is one of the most effective controls against account takeover.','[{"id":"passwords-get-stolen","heading":"Passwords get stolen","paragraphs":["Phishing, reused passwords and data breaches at other sites all expose credentials. A second factor means a stolen password alone is not enough to sign in."]},{"id":"where-to-turn-it-on","heading":"Where to turn it on","paragraphs":["Start with email, remote access and administrator accounts, then extend to every business application that supports it."],"list":["Email and office suite accounts","VPN and remote desktop","Cloud provider consoles","Finance and payroll systems"]},{"id":"choose-stronger-methods","heading":"Choose stronger methods","paragraphs":["App based prompts and hardware security keys resist phishing better than SMS codes. Use them where possible, especially for administrators."]}]'::jsonb),('writing-a-technology-roadmap','How to write a technology roadmap people will follow','Strategy','2026-06-03','AchiveX Editorial Team',false,'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?auto=format&fit=crop&w=1600&q=80','Roadmaps fail when they are too vague or too detailed. Here is a middle path.','A technology roadmap',' is a short, shared plan that links business goals to specific technology work over the next year or two. The best ones fit on a few pages.','[{"id":"tie-each-item-to-a-goal","heading":"Tie each item to a goal","paragraphs":["If an initiative cannot be linked to a business goal, question whether it belongs on the roadmap at all."]},{"id":"be-honest-about-capacity","heading":"Be honest about capacity","paragraphs":["A roadmap that assumes the team can do everything at once will slip. Plan around the people you actually have."]},{"id":"review-it-quarterly","heading":"Review it quarterly","paragraphs":["Priorities change. A short quarterly review keeps the roadmap useful instead of becoming a document nobody opens."]}]'::jsonb),('outsourcing-customer-support-checklist','A checklist before you outsource customer support','Operations','2026-05-11','AchiveX Editorial Team',false,'https://images.unsplash.com/photo-1600267185393-e158a98703de?auto=format&fit=crop&w=1600&q=80','The questions to answer internally so an outsourced team can represent you well.','Outsourcing customer support',' works well when the outside team has the same information your best internal agent would have. Use this checklist to get ready.','[{"id":"document-common-questions","heading":"Document common questions","paragraphs":["Pull the most frequent contact reasons from your inbox or helpdesk and write clear answers for each one."]},{"id":"agree-escalation-paths","heading":"Agree escalation paths","paragraphs":["Decide which issues the outsourced team can resolve and which must come back to your staff, and how quickly."]},{"id":"define-what-good-looks-like","heading":"Define what good looks like","paragraphs":["Set measures such as response time, resolution rate and quality scores before launch, so both sides know the target."]}]'::jsonb),('generative-ai-pilot-questions','Questions to answer before a generative AI pilot','Data','2026-04-02','AchiveX Editorial Team',false,'https://images.unsplash.com/photo-1531538606174-0f90ff5dce83?auto=format&fit=crop&w=1600&q=80','Clear answers to these questions make the difference between a useful pilot and an expensive demo.','A generative AI pilot',' should test whether a specific task gets faster or better with a language model. Answer these questions first.','[{"id":"what-task-are-you-testing","heading":"What task are you testing?","paragraphs":["Name the task, who does it today and how long it takes. Vague goals such as \"use AI more\" lead to vague results."]},{"id":"what-data-will-it-use","heading":"What data will it use?","paragraphs":["Decide which documents or records the model can see and confirm the provider terms for how that data is handled."]},{"id":"how-will-you-judge-it","heading":"How will you judge it?","paragraphs":["Prepare a set of test questions with known good answers and agree a pass mark before the pilot begins."]}]'::jsonb),('month-end-close-faster','Small changes that speed up the month end close','Operations','2026-02-19','AchiveX Editorial Team',false,'https://images.unsplash.com/photo-1554224154-26032ffc0d07?auto=format&fit=crop&w=1600&q=80','Practical steps finance teams can take without new software.','The month end close',' often takes longer than it should because work piles up in the last few days. Spreading it out helps.','[{"id":"reconcile-weekly","heading":"Reconcile weekly","paragraphs":["Bank and card reconciliations done each week leave far less to do at month end."]},{"id":"use-a-checklist","heading":"Use a checklist","paragraphs":["A written close checklist with owners and due dates prevents steps from being missed or repeated."]},{"id":"agree-cutoffs","heading":"Agree cutoffs","paragraphs":["Set clear cutoff dates for expense claims and invoices and share them with the whole company."]}]'::jsonb),('hybrid-infrastructure-basics','Hybrid infrastructure basics for growing companies','Cloud','2025-12-08','AchiveX Editorial Team',false,'https://images.unsplash.com/photo-1580894894513-541e068a3e2b?auto=format&fit=crop&w=1600&q=80','Not everything needs to move to the cloud. Here is how to decide what stays.','Hybrid infrastructure',' means running some systems in your own locations and others in the cloud, with secure connections between them.','[{"id":"what-often-stays-local","heading":"What often stays local","paragraphs":["Systems tied to physical equipment, very low latency needs or specific licensing terms are common reasons to keep workloads on site."]},{"id":"connect-them-securely","heading":"Connect them securely","paragraphs":["Use encrypted site to cloud connections and a single identity system so users and administrators sign in the same way everywhere."]},{"id":"monitor-both-sides","heading":"Monitor both sides","paragraphs":["One monitoring view across local and cloud systems avoids blind spots when something fails."]}]'::jsonb);
insert into public.case_studies (slug,title,client_type,industry,services,image,summary,overview,challenge,solution,results,sort) values ('retail-storefront-rebuild','Rebuilding an online store around mobile shoppers','Regional retail business','retail-and-ecommerce',array['digital-commerce','digital-marketing','digital-consulting-and-strategy']::text[],'https://images.unsplash.com/photo-1556740749-887f6717d7e4?auto=format&fit=crop&w=2000&q=80','A new storefront and checkout connected to inventory, with tracking to show what drives sales.','A retailer selling through a few physical stores and an online shop that has grown in pieces over several years.','["Most visitors arrive on mobile, but the checkout was designed for desktop and asks for the same details more than once.","Stock levels online are updated by hand from the store system, which leads to orders for items that are out of stock."]'::jsonb,'["We map the buying journey with your team and redesign the key pages for small screens first.","The store moves to a maintained commerce platform connected to the inventory system, so stock updates automatically.","Analytics and conversion tracking show the team where shoppers drop off."]'::jsonb,'["Checkout completion rate on mobile","Orders placed for out of stock items","Staff time spent updating stock by hand"]'::jsonb,0),('finance-reporting-consolidation','Consolidating finance reporting into one trusted model','Financial services firm','financial-services',array['data-modernization','advanced-analytics','data-management']::text[],'https://images.unsplash.com/photo-1590650153855-d9e808231d41?auto=format&fit=crop&w=2000&q=80','Monthly reports built from a single data model instead of spreadsheets maintained by different teams.','A finance team that builds monthly management reports by combining exports from several systems in spreadsheets.','["Different teams use different definitions for the same metrics, so numbers rarely match in leadership meetings.","Preparing the monthly pack relies on a few people and a lot of manual work."]'::jsonb,'["We run workshops to agree a shared set of metric definitions with finance and operations.","Source data loads into a cloud data warehouse through automated pipelines with reconciliation checks.","A reporting layer and a set of dashboards replace the manual pack."]'::jsonb,'["Days needed to produce the monthly report","Number of metric definitions in use across teams","Manual steps left in the reporting process"]'::jsonb,1),('logistics-cloud-migration','Moving a logistics platform to the cloud in planned stages','Logistics and distribution company','logistics',array['cloud-operations-and-migration','cloud-application-development-and-integration','staff-augmentation']::text[],'https://images.unsplash.com/photo-1494412574643-ff11b0a5c1c3?auto=format&fit=crop&w=2000&q=80','A staged migration of tracking and dispatch systems with tested rollback plans for each wave.','A distributor running shipment tracking and dispatch applications on ageing servers in a single location.','["Hardware is nearing end of support and any outage affects drivers and customers directly.","Several applications share a database, which makes a single big move risky."]'::jsonb,'["We document every application and dependency and group them into migration waves.","A cloud landing zone with networking, identity and monitoring is set up before any workload moves.","Each wave moves outside peak hours with a rehearsed cutover and rollback plan."]'::jsonb,'["Unplanned downtime during each migration wave","Monthly infrastructure cost before and after","Time to restore a service from backup"]'::jsonb,2),('healthcare-patient-support','Extending patient support hours with a trained contact team','Healthcare services provider','healthcare',array['contact-center','generative-ai']::text[],'https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?auto=format&fit=crop&w=2000&q=80','A dedicated contact team and a searchable knowledge base for appointment and billing questions.','A provider whose front desk staff answer patient calls while also managing in person visits.','["Callers wait on hold during busy clinic hours, and messages left after hours pile up.","Answers to common billing questions vary depending on who picks up the phone."]'::jsonb,'["We set up a contact team trained on your scheduling and billing policies.","A knowledge base written with your team is connected to an internal search assistant for agents.","Daily reports on contact reasons go to the practice manager."]'::jsonb,'["Average time callers wait on hold","Messages answered outside clinic hours","Consistency of answers in quality reviews"]'::jsonb,3),('manufacturing-equipment-monitoring','Connecting shop floor equipment to a live monitoring view','Mid sized manufacturer','manufacturing',array['connected-intelligence','digital-infrastructure-services','emerging-technologies']::text[],'https://images.unsplash.com/photo-1565514020179-026b92b84bb6?auto=format&fit=crop&w=2000&q=80','A pilot that brings machine status data into one dashboard for supervisors.','A plant where supervisors rely on walking the floor and paper logs to know which machines are running.','["Machines from different vendors store data in separate systems or not at all.","The plant network has grown without a plan and is not ready for more connected devices."]'::jsonb,'["We review the network and segment it to separate production equipment from office traffic.","A pilot connects a small group of machines through gateways to a cloud monitoring service.","Supervisors get a dashboard and alerts for stoppages."]'::jsonb,'["Time to notice a machine stoppage","Share of machines reporting live status","Planned versus unplanned maintenance"]'::jsonb,4),('education-security-program','Building a practical security baseline for a training provider','Education and training provider','education',array['security','managed-services','recruitment-process-outsourcing']::text[],'https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=2000&q=80','An assessment, prioritised fixes and ongoing monitoring sized for a small IT team.','An organisation with a small IT team supporting staff and students across several locations.','["There is no clear view of which risks matter most or where to start.","Some accounts are shared and multi factor authentication is not in use."]'::jsonb,'["We run an assessment against the CIS Controls and rank findings by risk.","Multi factor authentication, patching routines and backup testing come first.","Ongoing monitoring and quarterly reviews run through managed services."]'::jsonb,'["Accounts protected by multi factor authentication","Systems patched within the agreed window","Backups tested and restored successfully"]'::jsonb,5);
insert into public.news_posts (slug,published_on,title,summary,image,body) values ('achivex-launches-new-website','2026-10-19','AchiveX LLC launches its new website','The new site brings all AchiveX services, insights and contact options together in one place.','https://images.unsplash.com/photo-1504711434969-e33886168f5c?auto=format&fit=crop&w=1600&q=80','["AchiveX LLC has launched its new website at achivex.com. The site describes the full range of services the company offers, from digital strategy and data to cloud, security and business process support.","Each service now has its own page with a plain description of what is included, how the work is carried out and answers to common questions. Visitors can also read articles, download free guides and book a free consultation.","Questions about the new site or any of the services can be sent to info@achivex.com or by phone on +1 307 622 1140."]'::jsonb),('free-guides-library','2026-10-19','Free guides now available to download','Four practical guides on cloud migration, data quality, generative AI and security are now free to download.','https://images.unsplash.com/photo-1495020689067-958852a7765e?auto=format&fit=crop&w=1600&q=80','["AchiveX has published a library of free guides written for small and mid sized businesses. The first four cover cloud migration planning, data quality, choosing generative AI use cases and a basic security baseline.","Each guide focuses on practical steps a team can take without a large budget. They are available from the Whitepapers and eBooks section of the website."]'::jsonb),('seven-service-areas','2026-10-19','AchiveX outlines its seven service areas','Digital, Data and Analytics, Cloud, Digital Infrastructure, Security, Emerging Technologies and Business Process Services.','https://images.unsplash.com/photo-1540575467063-178a50c2df87?auto=format&fit=crop&w=1600&q=80','["AchiveX organises its work into seven service areas: Digital, Data and Analytics, Cloud, Digital Infrastructure Services, Security, Emerging Technologies and Business Process Services.","Clients can start with a single service and add others as their needs grow. Every engagement begins with a free consultation to understand goals, current systems and budget."]'::jsonb);
insert into public.whitepapers (slug,title,type,description,cover,inside,file_url,sort) values ('cloud-migration-planning-guide','Cloud Migration Planning Guide','eBook','A practical walk through of discovery, wave planning and cutover for small and mid sized teams.','https://images.unsplash.com/photo-1532012197267-da84d127e765?auto=format&fit=crop&w=900&q=80','["How to build an application and dependency inventory","Choosing between rehost, replatform and refactor","A sample wave plan and cutover checklist","Cost questions to answer before you move"]'::jsonb,null,0),('data-quality-starter-kit','Data Quality Starter Kit','Whitepaper','Simple routines for measuring and improving data quality without a large governance programme.','https://images.unsplash.com/photo-1481627834876-b7833e8f5570?auto=format&fit=crop&w=900&q=80','["The six dimensions of data quality explained plainly","How to pick the first data area to fix","Assigning data owners in a small organisation","A template for a monthly quality review"]'::jsonb,null,1),('generative-ai-use-case-workbook','Generative AI Use Case Workbook','eBook','Questions and scoring sheets to help you choose sensible first projects for generative AI.','https://images.unsplash.com/photo-1512820790803-83ca734da794?auto=format&fit=crop&w=900&q=80','["Spotting tasks that suit language models","Scoring value, risk and data readiness","Planning a small proof of concept","Questions to ask model providers about data use"]'::jsonb,null,2),('small-business-security-baseline','Small Business Security Baseline','Whitepaper','The core controls that address common attacks, mapped to the CIS Controls Implementation Group 1.','https://images.unsplash.com/photo-1543002588-bfa74002ed7e?auto=format&fit=crop&w=900&q=80','["Why identity and multi factor authentication come first","Patching and asset inventory routines","Backup testing that actually proves recovery","A one page incident response starter plan"]'::jsonb,null,3);
insert into public.milestones (year,title,description,sort) values ('2026','New website and service catalog','AchiveX launched its new website describing seven service areas and twenty individual services.',0);
